class LaserWeapon {
    constructor(damage) {
        this.damage = damage;
    }

    fire(target) {
        const damageDealt = this.damage;
        target.takeDamage(damageDealt);
        return `fires a laser, dealing ${damageDealt} damage!`;
    }

    getDamage() {
        return this.damage;
    }
}

class RobotDefender {
    constructor(name, health, weapon) {
        this.name = name;
        this.health = health;
        this.weapon = weapon;
    }

    takeDamage(amount) {
        this.health -= amount;
        if (this.health < 0) this.health = 0;
        return `${this.name} took ${amount} damage. Current health: ${this.health}`;
    }

    attack(target) {
        const attackMessage = this.weapon.fire(target);
        return `${this.name} ${attackMessage}`;
    }

    getHealth() {
        return this.health;
    }
}

// Example Usage:
const laserCannon = new LaserWeapon(25);
const plasmaBlaster = new LaserWeapon(18);

const defender1 = new RobotDefender("Sentinel", 100, laserCannon);
const defender2 = new RobotDefender("GuardBot", 80, plasmaBlaster);

// Test interactions
console.log(defender1.attack(defender2));
console.log(`Defender 2 Health: ${defender2.getHealth()}`);
console.log(defender2.attack(defender1));
console.log(`Defender 1 Health: ${defender1.getHealth()}`);

